// 🔐 Senha do relatório (troque aqui)
const SENHA = '<SEGREDO_REMOVIDO>';
const q = $('Abrir relatório (GET)').first().json.query || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const pagina = (corpo, refresh) => `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">${refresh ? '<meta http-equiv="refresh" content="10">' : ''}<title>Relatório do Instagram</title>
<style>body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:#fafafa;color:#262626;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;padding:20px;text-align:center}.c{max-width:420px;background:#fff;border:1px solid #dbdbdb;border-radius:16px;padding:28px}
input{width:100%;padding:12px;border:1px solid #dbdbdb;border-radius:10px;font:inherit;margin:14px 0 10px;box-sizing:border-box}button{width:100%;padding:12px;border:0;border-radius:10px;background:#0095f6;color:#fff;font:inherit;font-weight:700;cursor:pointer}.s{width:44px;height:44px;border:4px solid #efefef;border-top-color:#dd2a7b;border-radius:50%;margin:0 auto 16px;animation:r .8s linear infinite}@keyframes r{to{transform:rotate(360deg)}}p{color:#8e8e8e}.er{color:#d03b3b;font-weight:600}</style></head><body><div class="c">${corpo}</div></body></html>`;

if (q.senha !== SENHA) {
  return [{ json: { acao: 'login', codigo: q.senha ? 401 : 200, html: pagina(`<div style="font-size:40px">📈</div><h2>Relatório do Instagram</h2><p>Digite a senha do relatório</p><form method="get"><input name="senha" type="password" placeholder="Senha" autofocus required aria-label="Senha">${q.senha ? '<p class="er">Senha incorreta.</p>' : ''}<button>Ver relatório</button></form>`) } }];
}
const cache = $('Lê relatório salvo').first().json.relatorio;
const trava = $('Lê trava').first().json.trava;
const espera = pagina('<div class="s"></div><h2>Analisando o perfil…</h2><p>Lendo os últimos 30 posts e pedindo a análise para a IA. Leva cerca de 1 minuto e esta página se atualiza sozinha.</p>', true);
if (cache && q.atualizar !== '1') return [{ json: { acao: 'mostrar', relatorio: cache } }];
if (trava) return [{ json: { acao: 'esperar', codigo: 200, html: espera } }];
return [{ json: { acao: 'gerar', codigo: 200, html: espera } }];

const R = JSON.parse($input.first().json.relatorio);
const q = $('Abrir relatório (GET)').first().json.query || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const num = n => Number(n || 0).toLocaleString('pt-BR');
const dec = n => String(Number(n || 0).toFixed(1)).replace('.', ',');
const P = R.perfil || {}, ia = R.ia;
const fuso = { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' };

const barras = (itens, rotulo) => {
  const max = Math.max(1, ...itens.map(i => i.media));
  return itens.map(i => `<div class="hb"><span class="hl">${esc(i.nome)}</span><span class="ht"><span class="hf" tabindex="0" data-tip="${esc(i.nome)}: média de ${dec(i.media)} interações em ${i.posts} post${i.posts === 1 ? '' : 's'}" style="width:calc((100% - 92px) * ${(i.media / max).toFixed(4)})"></span><span class="hv">${dec(i.media)} <small>· ${i.posts} ${i.posts === 1 ? rotulo.replace(/s$/, '') : rotulo}</small></span></span></div>`).join('');
};
let blocoIA = '<div class="card c12"><h2>🤖 Análise da IA</h2><p class="mu">A IA não respondeu desta vez. Clique em Atualizar para tentar de novo.</p></div>';
if (ia) {
  const n = Math.max(0, Math.min(100, Number(ia.nota_saude) || 0));
  const st = n >= 70 ? ['var(--bom)', '✅', 'Perfil saudável'] : n >= 40 ? ['var(--alerta)', '⚠️', 'Pode melhorar'] : ['var(--critico)', '🔴', 'Precisa de atenção'];
  const li = arr => (Array.isArray(arr) ? arr : []).slice(0, 5).map(x => `<li>${esc(x)}</li>`).join('');
  blocoIA = `<div class="card c12 ia"><h2>🤖 Análise da IA</h2><div class="saude"><span class="ponto" style="background:${st[0]}"></span>${st[1]} ${st[2]} · nota ${n} de 100</div>
  <p>${esc(ia.resumo)}</p>
  <div class="duas"><div><h3>💪 O que está funcionando</h3><ul>${li(ia.o_que_funciona)}</ul></div><div><h3>🔧 O que melhorar</h3><ul>${li(ia.o_que_melhorar)}</ul></div></div>
  <p class="mu" style="margin-top:10px">📅 Melhor dia: <b>${esc(ia.melhor_dia)}</b> · ⏰ Melhor horário: <b>${esc(ia.melhor_horario)}</b> · 🔁 Frequência sugerida: <b>${esc(ia.frequencia_recomendada)}</b></p>
  <h3>💡 Ideias para os próximos posts</h3><div class="ideias">${(Array.isArray(ia.ideias) ? ia.ideias : []).slice(0, 6).map(i => `<div class="ideia"><span class="tag">${esc(i.formato)}</span><b>${esc(i.titulo)}</b><p>“${esc(i.gancho)}”</p><small>${esc(i.por_que)}</small></div>`).join('')}</div></div>`;
}
const PL = R.plano || {}, MX = PL.mix_formatos || {}, CA = R.calendario || {};
const NOMEF = { carrossel: '🎠 Carrossel', post: '📷 Post', reels: '🎬 Reels' };
const blocoPlano = `<div class="card c12 plano"><h2>📅 Plano para o próximo mês</h2><p class="mu">O fluxo <b>30 Dias de Posts</b> usa este diagnóstico: escolhe quantos posts de cada formato, o melhor horário e corrige o que está em “O que melhorar”.</p><div class="mix">${['carrossel', 'post', 'reels'].map(f => `<span class="tag">${NOMEF[f]}: <b>${MX[f] || 0}</b> dias</span>`).join('')}${PL.hora_sugerida ? `<span class="tag">⏰ publicar às <b>${esc(PL.hora_sugerida)}</b></span>` : ''}</div>${CA.posts ? `<h3>📊 Posts que vieram do calendário de 30 dias</h3><p class="mu">${CA.posts} post${CA.posts === 1 ? '' : 's'} do calendário: média de <b>${dec(CA.media_calendario)}</b> interações x <b>${dec(CA.media_outros)}</b> dos outros posts.</p>${barras(CA.por_pilar || [], 'posts')}` : ''}<a class="btn cta" href="posts30?diag=1">📅 Criar 30 dias de posts com base neste diagnóstico</a></div>`;
const top = (R.top || []).map((p, i) => `<a class="top" href="${esc(p.link)}" target="_blank" rel="noopener">${p.imagem ? `<img src="${esc(p.imagem)}" alt="" loading="lazy">` : '<span class="semimg">🎬</span>'}<span><b>#${i + 1} · ${num(p.interacoes)} interações</b><small>${esc(p.formato)} · ${esc(p.dia)} às ${p.hora}h · ❤️ ${num(p.curtidas)} · 💬 ${num(p.comentarios)}</small><em>${esc(p.legenda)}</em></span></a>`).join('');
const linhas = (R.lista || []).map(p => `<tr><td>${esc(new Date(p.data).toLocaleString('pt-BR', fuso))}</td><td>${esc(p.formato)}</td><td>${num(p.curtidas)}</td><td>${num(p.comentarios)}</td><td>${dec(p.engajamento)}%</td></tr>`).join('');
const s = R.resumo || {};
const link = `?senha=${encodeURIComponent(q.senha || '')}&atualizar=1`;

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Relatório · @${esc(P.username)}</title>
