<div class="grid">
<div class="card c3 hero"><div class="lab">Engajamento médio</div><div class="val">${dec(s.engajamento_medio_percent)}%</div><div class="det">(curtidas + comentários) ÷ seguidores${Number(P.followers_count) < 100 ? ' · com menos de 100 seguidores esse número distorce' : ''}</div></div>
<div class="card c3"><div class="lab">Curtidas por post</div><div class="val">${dec(s.media_curtidas)}</div><div class="det">média dos ${s.posts_analisados} últimos posts</div></div>
